// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(uint256 difficultyValue) public {
        // Bound the difficulty to a reasonable range
        uint256 boundDifficulty = bound(difficultyValue, 1, 1000);

        // Make the contract open to public
        c.OpenToThePublic();

        // Adjust difficulty to a non-zero value
        c.AdjustDifficulty(boundDifficulty);

        // Now adjust bet limit - this should NOT change the difficulty
        c.AdjustBetAmounts(100);

        // The difficulty should still be the previously set value
        assertTrue(c.currentDifficulty() == boundDifficulty);
    }
}

